UPDATE icam20_price
   SET icam20_item_nm = #{itemName}
 WHERE icam20_item_type = #{itemType}
   AND icam20_isin      = #{isin}
   AND icam20_std_date != #{stdDate}

UPDATE  flt10_tr
   SET  flt10_item_nm = #{itemName}
 WHERE  flt10_item_cd = #{isin}

UPDATE  flt10_tr
   SET  flt10_tr_item_nm = #{itemName}
 WHERE  flt10_tr_item_cd = #{isin}

UPDATE  flt11_book
   SET  flt11_item_nm = #{itemName}
 WHERE  flt11_item_cd = #{isin}

UPDATE  flt12_book_month
   SET  flt12_item_nm = #{itemName}
 WHERE  flt12_item_cd = #{isin}

UPDATE  flt13_book_init
   SET  flt13_item_nm = #{itemName}
 WHERE  flt13_item_cd = #{isin}
